// One Telegram message per row from script_approvals_due(), sent after script.md (Vietnamese, D-061).
// Callback data stays under Telegram's 64-byte limit: a1:<A|G|R>:<32-hex token>. Episodes (D-050)
// are counted in acts and shots; Shorts in scenes. Reminders carry no preview.
// Shared Telegram formatting (same in every approval message node): the text goes out as HTML,
// times in Vietnam time (UTC+7, no daylight saving), and the request token rides in a hidden link
// at the start, so a reply to the message finds its request (WF-06) without showing the token.
const esc = (value) => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const vnTime = (value) => {
  const d = new Date(new Date(value).getTime() + 7 * 3_600_000);
  const p = (n) => String(n).padStart(2, '0');
  return `${p(d.getUTCHours())}:${p(d.getUTCMinutes())} ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}`;
};
const hiddenRef = (kind, token) => `<a href="https://t.me/?${kind}=${token}">\u200d</a>`;
const PREVIEW_CHARS = 2500;
const size = (script) => script.format === 'episode'
  ? `~${((script.total_seconds ?? 0) / 60).toFixed(1)} phút · ${script.act_count ?? '?'} hồi · ${script.shot_count ?? '?'} shot · ${script.line_count ?? '?'} câu`
  : `${script.total_seconds ?? '?'} giây · ${script.scene_count ?? '?'} cảnh`;
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
return rows.map(({ json: row }) => {
  const script = (typeof row.script === 'string' ? JSON.parse(row.script) : row.script) || {};
  const shortId = String(row.video_id).slice(0, 8);
  const reminder = row.kind === 'REMINDER';
  // tts_estimate is what approving accepts as the TTS budget (D-023); null means no price is set.
  const estimate = script.tts_estimate;
  const budget = estimate
    ? `TTS tối đa ${estimate.amount} ${estimate.currency === 'CRD' ? 'credit ITERA' : estimate.currency} (${estimate.units} ký tự)`
    : '⚠️ Chưa cấu hình giá TTS: duyệt sẽ không cho chi tiền TTS';
  const preview = String(script.preview ?? '').slice(0, PREVIEW_CHARS);
  const html = [
    `${hiddenRef('kb', row.token)}<b>${reminder ? '⏰ Nhắc: ' : ''}📝 Duyệt kịch bản</b> · bước 1/5 · A1`,
    `«${esc(script.title ?? '?')}»`,
    `#${shortId} v${row.version} · ${size(script)}`,
    esc(budget),
    ...(!reminder && preview ? [`<blockquote expandable>${esc(preview)}</blockquote>`] : []),
    `⏰ Hạn ${vnTime(row.expires_at)} · ↩️ Reply tin này để góp ý sửa`,
  ].join('\n');
  return { json: { html, approve: `a1:A:${row.token}`, regenerate: `a1:G:${row.token}`, reject: `a1:R:${row.token}` } };
});

// One item per new A1 request with a script file (reminders send none): the worker serves script.md
// against the script job's media token (D-070). Replace the base URL on import. ASCII file name.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST');
return rows.flatMap(({ json: row }) => {
  const script = (typeof row.script === 'string' ? JSON.parse(row.script) : row.script) || {};
  const file = script.file;
  if (!file || typeof file.job_id !== 'string' || typeof file.token !== 'string') return [];
  const shortId = String(row.video_id).slice(0, 8);
  return [{
    json: {
      url: `${WORKER}/media/${row.video_id}/${row.version}/${file.job_id}/script.md?t=${file.token}`,
      fileName: `script-${shortId}-v${row.version}.md`,
      caption: `📝 #${shortId} v${row.version} · kịch bản đầy đủ`,
    },
  }];
});
